import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.CAKCj7G0.js";const h=JSON.parse('{"title":"Queue","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/集合/Collection/Queue/Queue.md","filePath":"Java/Java/集合/Collection/Queue/Queue.md","lastUpdated":1762838572000}'),u={name:"Java/Java/集合/Collection/Queue/Queue.md"};function l(i,e,r,a,n,s){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="queue" tabindex="-1">Queue <a class="header-anchor" href="#queue" aria-label="Permalink to &quot;Queue&quot;">​</a></h1><h1 id="一、queue-接口的核心定位" tabindex="-1">一、Queue 接口的核心定位 <a class="header-anchor" href="#一、queue-接口的核心定位" aria-label="Permalink to &quot;一、Queue 接口的核心定位&quot;">​</a></h1><p>Queue 接口是 Java 集合框架的核心成员，它定义了一个**先进先出（FIFO）**的数据结构规范，专注于“队列”的基础操作，不包含具体实现逻辑。直接继承自 <code>Collection</code> 接口，主要用于处理需要按“顺序排队”的场景，例如任务队列、消息队列等。</p><h2 id="_1-核心特性" tabindex="-1">1. 核心特性 <a class="header-anchor" href="#_1-核心特性" aria-label="Permalink to &quot;1. 核心特性&quot;">​</a></h2><ol><li><p><strong>FIFO 原则</strong>：默认情况下，元素的插入（尾部）和移除（头部）遵循“先进先出”规则，与现实中的排队逻辑一致。</p></li><li><p><strong>双端扩展</strong>：部分实现类（如 <code>LinkedList</code>）实现了 <code>Deque</code> 接口，支持从头部和尾部双向操作，突破了纯 FIFO 限制。</p></li><li><p><strong>操作两种风格</strong>：所有核心操作都提供“抛出异常”和“返回特殊值”两种版本，适配不同的业务容错需求。</p></li></ol><h1 id="二、queue-接口的核心方法" tabindex="-1">二、Queue 接口的核心方法 <a class="header-anchor" href="#二、queue-接口的核心方法" aria-label="Permalink to &quot;二、Queue 接口的核心方法&quot;">​</a></h1><p>Queue 接口的方法可分为<strong>插入、移除、查看</strong>三类，每类方法都有两种行为风格，是学习的核心重点。</p><table tabindex="0"><thead><tr><th>操作类型</th><th>抛出异常（失败时）</th><th>返回特殊值（失败时）</th><th>方法作用</th></tr></thead><tbody><tr><td>插入</td><td><code>add(E e)</code></td><td><code>offer(E e)</code></td><td>向队列尾部添加元素</td></tr><tr><td>移除</td><td><code>remove()</code></td><td><code>poll()</code></td><td>移除并返回队列头部元素</td></tr><tr><td>查看</td><td><code>element()</code></td><td><code>peek()</code></td><td>仅返回队列头部元素（不移除）</td></tr></tbody></table><h2 id="_1-方法详解" tabindex="-1">1. 方法详解 <a class="header-anchor" href="#_1-方法详解" aria-label="Permalink to &quot;1. 方法详解&quot;">​</a></h2><ul><li><p><strong>add(E e) vs offer(E e)</strong>：两者均添加元素，<code>add</code> 在队列满（如固定容量队列）时抛出 <code>IllegalStateException</code>，<code>offer</code> 则返回 <code>false</code>，更适合非阻塞场景。</p></li><li><p><strong>remove() vs poll()</strong>：两者均移除头部元素，<code>remove</code> 在队列为空时抛出 <code>NoSuchElementException</code>，<code>poll</code> 则返回 <code>null</code>，需注意判断返回值是否为 <code>null</code>（若队列存 <code>null</code> 元素会有歧义）。</p></li><li><p><strong>element() vs peek()</strong>：两者均查看头部元素，<code>element</code> 在队列为空时抛出 <code>NoSuchElementException</code>，<code>peek</code> 则返回 <code>null</code>，用法与移除类方法逻辑一致。</p></li></ul><h1 id="三、queue-与相关接口的关系" tabindex="-1">三、Queue 与相关接口的关系 <a class="header-anchor" href="#三、queue-与相关接口的关系" aria-label="Permalink to &quot;三、Queue 与相关接口的关系&quot;">​</a></h1><p>Queue 接口并非孤立存在，它与 <code>Collection</code>、<code>Deque</code>、<code>BlockingQueue</code> 等接口形成了清晰的继承和扩展关系，理解这些关系能更好地定位其用途。</p><h2 id="_1-继承关系" tabindex="-1">1. 继承关系 <a class="header-anchor" href="#_1-继承关系" aria-label="Permalink to &quot;1. 继承关系&quot;">​</a></h2><ul><li><p><strong>父接口</strong>：直接继承 <code>Collection</code> 接口，因此拥有 <code>size()</code>、<code>isEmpty()</code>、<code>contains(Object o)</code> 等 Collection 通用方法。</p></li><li><p><strong>子接口</strong> <strong>：</strong></p><ul><li><p><code>Deque</code>：双端队列接口，扩展了 Queue，支持从头部/尾部插入、移除元素（如 <code>addFirst(E e)</code>、<code>pollLast()</code>），实现类有 <code>LinkedList</code>、<code>ArrayDeque</code>。</p></li><li><p><code>BlockingQueue</code>：阻塞队列接口，在 Queue 基础上增加了“阻塞等待”特性（如队列满时等待空间、队列空时等待元素），是多线程编程的核心工具，实现类有 <code>ArrayBlockingQueue</code>、<code>LinkedBlockingQueue</code>。</p></li><li><p><code>BlockingDeque</code>：阻塞双端队列接口，继承 <code>Deque</code> 和 <code>BlockingQueue</code>，支持双端阻塞操作，适合需要双向阻塞访问的场景，实现类如 <code>LinkedBlockingDeque</code>。</p></li><li><p><code>TransferQueue</code>：传递队列接口，继承 <code>BlockingQueue</code>，新增“生产者直接传递元素给消费者”的特性，实现类如 <code>LinkedTransferQueue</code>。</p></li></ul></li></ul><h2 id="_2-与-list-接口的区别" tabindex="-1">2. 与 List 接口的区别 <a class="header-anchor" href="#_2-与-list-接口的区别" aria-label="Permalink to &quot;2. 与 List 接口的区别&quot;">​</a></h2><p>Queue 与同为 Collection 子接口的 List（如 <code>ArrayList</code>、<code>LinkedList</code>）定位差异显著，核心区别在“操作目标”和“顺序规则”：</p><table tabindex="0"><thead><tr><th>对比维度</th><th>Queue 接口</th><th>List 接口</th></tr></thead><tbody><tr><td>核心定位</td><td>按“队列规则”操作（头部/尾部）</td><td>按“索引”随机访问（任意位置）</td></tr><tr><td>顺序规则</td><td>默认 FIFO，可通过 Deque 扩展</td><td>元素顺序由插入顺序或排序规则决定</td></tr><tr><td>核心方法</td><td>聚焦 add/offer、remove/poll 等队列操作</td><td>聚焦 get(int index)、set(int index, E e) 等索引操作</td></tr></tbody></table><h1 id="四、queue-接口的典型实现类-非接口本身-仅作关联参考" tabindex="-1">四、Queue 接口的典型实现类（非接口本身，仅作关联参考） <a class="header-anchor" href="#四、queue-接口的典型实现类-非接口本身-仅作关联参考" aria-label="Permalink to &quot;四、Queue 接口的典型实现类（非接口本身，仅作关联参考）&quot;">​</a></h1><p>Queue 是接口，需通过实现类使用，常见实现类的特性如下（了解实现类可更好地理解接口设计意图）：</p><ul><li><p><strong>LinkedList</strong>：实现了 <code>Queue</code> 和 <code>Deque</code> 接口，基于链表实现，支持双端操作，无固定容量限制，同时也实现了 <code>List</code> 接口可兼顾索引访问。</p></li><li><p><strong>ArrayDeque</strong>：实现了 <code>Deque</code> 接口，基于动态数组实现，双端操作（增删头尾）效率极高，无容量限制（自动扩容），是 <code>Stack</code> 类的推荐替代者。</p></li><li><p><strong>PriorityQueue</strong>：实现了 <code>Queue</code> 接口，<strong>打破 FIFO 规则</strong>，按元素优先级排序（默认自然排序或自定义 <code>Comparator</code>），基于数组实现堆结构，头部始终是优先级最高元素。</p></li><li><p><strong>ArrayBlockingQueue</strong>：实现了 <code>BlockingQueue</code> 接口，基于数组的有界阻塞队列，创建时需指定容量，支持公平/非公平访问策略，多线程场景中常用。</p></li><li><p><strong>LinkedBlockingQueue</strong>：实现了 <code>BlockingQueue</code> 接口，基于链表实现，默认无界（容量为 <code>Integer.MAX_VALUE</code>），也可指定容量，并发性能优于 <code>ArrayBlockingQueue</code>。</p></li><li><p><strong>LinkedBlockingDeque</strong>：实现了 <code>BlockingDeque</code> 接口，基于链表的阻塞双端队列，支持双向阻塞增删，适合需要双向调度的多线程场景（如线程池任务调度）。</p></li><li><p><strong>ConcurrentLinkedQueue</strong>：实现了 <code>Queue</code> 接口，基于链表的无界非阻塞队列，采用 CAS 算法保证并发安全，无锁设计使其在高并发场景下性能优异。</p></li><li><p><strong>DelayQueue</strong>：实现了 <code>BlockingQueue</code> 接口，专门存储带延迟时间的元素，元素仅在延迟到期后才可被取出，常用于定时任务调度场景（如订单超时取消）。</p></li></ul><h1 id="五、queue-接口的使用注意事项" tabindex="-1">五、Queue 接口的使用注意事项 <a class="header-anchor" href="#五、queue-接口的使用注意事项" aria-label="Permalink to &quot;五、Queue 接口的使用注意事项&quot;">​</a></h1><ol><li><p><strong>null 元素限制</strong>：多数 Queue 实现类（如 <code>PriorityQueue</code>、<code>BlockingQueue</code> 子类、<code>ConcurrentLinkedQueue</code>）不允许插入 <code>null</code> 元素，插入 <code>null</code> 会抛出 <code>NullPointerException</code>；仅 <code>LinkedList</code> 允许 <code>null</code>，但不推荐（会影响 <code>poll()</code> 方法的 <code>null</code> 判断逻辑）。</p></li><li><p><strong>容量限制差异</strong>： 无界队列：如 <code>LinkedList</code>、<code>PriorityQueue</code>、<code>ConcurrentLinkedQueue</code>，理论上容量可无限增长（受内存限制），<code>add()</code> 方法不会因容量问题抛出异常。</p></li><li><p>有界队列：如 <code>ArrayBlockingQueue</code>、<code>LinkedBlockingQueue</code>（指定容量时）、<code>LinkedBlockingDeque</code>（指定容量时），满容量时 <code>add()</code> 抛异常，<code>offer()</code> 返回 <code>false</code>。</p></li><li><p><strong>PriorityQueue 的特殊排序</strong>：<code>PriorityQueue</code> 是 Queue 接口的“特殊实现”，其 <code>peek()</code>/<code>poll()</code> 返回的是优先级最高的元素，而非最早插入的元素，使用时需注意排序规则（自定义 <code>Comparator</code> 时需确保逻辑正确）。</p></li><li><p><strong>并发安全问题</strong>：普通实现类（如 <code>LinkedList</code>、<code>ArrayDeque</code>、<code>PriorityQueue</code>）均非线程安全，多线程环境下需手动加锁；若需并发安全，优先选择 <code>ConcurrentLinkedQueue</code>（非阻塞）或 <code>BlockingQueue</code> 子类（阻塞）。</p></li></ol>',22)])])}const g=o(u,[["render",l]]);export{h as __pageData,g as default};
